fonctions.exemple:
#rdtabnum(width: 5.5cm, stop: "unites",
  rdtnplace("5,4"), rdtnplace(5400),
  rdtnsurcouche(g => {
    let a = (g.droite)(1)
    let b = (g.droite)(2)
    place(top + left, dx: a.x, dy: a.y,
      curve(stroke: teal + 1pt,
        curve.move((0pt, 0pt)),
        curve.cubic((1.4cm, 0pt), (1.4cm, b.y - a.y), (0pt, b.y - a.y))))
  }))

